const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_BASE_PREMIUM = 25;

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const itemBasePremium = (item: Item): number =>
  BASE_PREMIUMS[item.type] ?? COMPONENT_BASE_PREMIUM;

export const calculatePremium = (
  customer: Customer,
  items: Item[],
  isFirstContract: boolean,
): number => {
  if (items.length === 0) return PROCESSING_FEE;
  const basePremium = items.reduce((sum, item) => sum + itemBasePremium(item), 0);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
};

