import { describe, it, expect } from "vitest";
import { calculatePremium } from "./premium.js";

describe("Premium calculation", () => {
  // Edge cases — simplest
  it("empty item list → premium 5 G (only the processing fee)", () => {
    expect(calculatePremium({ yearsWithMHPCO: 0 }, [], true)).toBe(5);
  });

  // Base premiums for main items (newcomer, no modifiers except first-insurance+fee)
  it("single sword (newcomer) → base 100 G + 10 G first insurance + 5 G fee = 115 G", () => {
    expect(
      calculatePremium({ yearsWithMHPCO: 0 }, [{ type: "sword" }], true),
    ).toBe(115);
  });
  it("single amulet (newcomer) → base 60 G + 6 G first insurance + 5 G fee = 71 G", () => {
    expect(
      calculatePremium({ yearsWithMHPCO: 0 }, [{ type: "amulet" }], true),
    ).toBe(71);
  });
  it("single staff (newcomer) → base 80 G + 8 G first insurance + 5 G fee = 93 G", () => {
    expect(
      calculatePremium({ yearsWithMHPCO: 0 }, [{ type: "staff" }], true),
    ).toBe(93);
  });
  it("single potion (newcomer) → base 40 G + 4 G first insurance + 5 G fee = 49 G", () => {
    expect(
      calculatePremium({ yearsWithMHPCO: 0 }, [{ type: "potion" }], true),
    ).toBe(49);
  });

  // Component building block base premiums (isolated, before fee/modifiers) —
  // verified via newcomer quotes so we can check the final integer premium
  it("2 runes (newcomer) → base premium 50 G (no block)", () => {
    expect(
      calculatePremium(
        { yearsWithMHPCO: 0 },
        [{ type: "rune" }, { type: "rune" }],
        true,
      ),
    ).toBe(60);
  });
  it("3 runes (newcomer) → base premium 60 G (block applies)", () => {
    expect(
      calculatePremium(
        { yearsWithMHPCO: 0 },
        [{ type: "rune" }, { type: "rune" }, { type: "rune" }],
        true,
      ),
    ).toBe(71);
  });
  it("4 runes (newcomer) → base premium 100 G (no block — requires exactly 3)", () => {
    expect(
      calculatePremium(
        { yearsWithMHPCO: 0 },
        [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }],
        true,
      ),
    ).toBe(115);
  });
  it("7 runes (newcomer) → base premium 175 G, final premium rounds up to 198 G", () => {
    expect(
      calculatePremium(
        { yearsWithMHPCO: 0 },
        Array(7).fill({ type: "rune" }),
        true,
      ),
    ).toBe(198);
  });
  it("2 runes + 1 moonstone (newcomer) → base premium 75 G (no block: different types)", () => {
    expect(
      calculatePremium(
        { yearsWithMHPCO: 0 },
        [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
        true,
      ),
    ).toBe(88);
  });
  it("3 runes + 3 moonstones (newcomer) → base premium 120 G (two separate blocks)", () => {
    expect(
      calculatePremium(
        { yearsWithMHPCO: 0 },
        [
          { type: "rune" },
          { type: "rune" },
          { type: "rune" },
          { type: "moonstone" },
          { type: "moonstone" },
          { type: "moonstone" },
        ],
        true,
      ),
    ).toBe(137);
  });

  // Item-specific modifiers: cursed, high enchantment
  it.todo("cursed sword (newcomer) → base 100 G + 50 G curse surcharge + 10 G first insurance + 5 G fee = 165 G (newcomer with cursed sword example)");
  it.todo("sword with enchantment exactly 5 (newcomer) → high-enchantment surcharge applies: 100 + 30 + 10 + 5 = 145 G");
  it.todo("sword with enchantment exactly 5, cursed (newcomer) → both surcharges apply: 100 + 50 + 30 + 10 + 5 = 195 G");
  it.todo("sword with enchantment 4 (newcomer, not cursed) → no high-enchantment surcharge: 100 + 10 + 5 = 115 G");
  it.todo("sword with enchantment 4, cursed (newcomer) → curse surcharge only: 100 + 50 + 10 + 5 = 165 G");

  // Policy-wide modifier scope on multi-item policies
  it.todo("policy with cursed sword + plain amulet (newcomer) → policy base 160 G, curse surcharge 50 G (on sword's base only) → 210 G + 10% first insurance (21G) + 5 G fee = 236 G");

  // Loyalty discount threshold
  it.todo("customer with exactly 2 years with MHPCO, single sword (first contract) → loyalty discount applies: (100 - 20) + 10 first-insurance + 5 fee = 95 G");

  // Follow-up contract discount + first-insurance-per-item clarification
  it.todo("long-standing customer's second contract: 3 years, cursed sword enchantment 7 → premium 160 G (100 base + 50 curse + 30 high-enchantment - 20 loyalty + 10 first-insurance - 15 follow-up + 5 fee)");

  // Rounding
  it.todo("premium calculation yielding 197.5 G → rounds up to 198 G");

  // Multiple items of the same type (insurance sum / cap, verified via claim tests below)
  it.todo("policy with two swords → insurance sum 2000 G, cap 4000 G (verified via claim remainingCap)");

  // Error cases for quote
  it.todo("quote with unknown item type (e.g. broomstick) → CLI exits non-zero, writes error to stderr, no results written");
});

describe("Claim processing", () => {
  // Simplest / standard reimbursement
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G (full reimbursement minus 100 G deductible)");
  it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G (full reimbursement minus deductible; no special clause)");

  // Special clauses
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G (high-enchantment clause: 50% then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (both clauses apply; 50% rule wins, then deductible)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (only dragon-material clause: full reimbursement, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (only high-enchantment clause: 50% then deductible)");

  // Deductible per damage event
  it.todo("dragon attack damages insured sword (500 G) and insured amulet (300 G) → payout 600 G (100 G deductible applies once per damaged item)");

  // Multiple items of same type
  it.todo("policy covers two swords; damages array has two sword entries → each treated as separate damage with its own deductible");
  it.todo("damages array has more entries of a type than policy covers (e.g. two sword damages but only one sword insured) → CLI exits non-zero, whole claim rejected");

  // Cap exhaustion
  it.todo("policy covers sword + amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("cursed sword (insurance value 1000 G, premium 165 G with modifiers) → cap 2000 G (based on unmodified insurance value)");
  it.todo("policy covers sword + 3 runes (a block) → insurance sum 1750 G (block discount affects premium only, not insurance sum)");
  it.todo("sword insured (cap 2000 G); two successive claims of 1500 G each → first payout 1400 G, cap remaining 600 G; second payout 600 G, cap remaining 0 G");

  // Rounding
  it.todo("payout calculation yielding 350.5 G → rounds down to final payout 350 G");

  // Error cases for claim
  it.todo("claim references damage entry whose item is not part of the policy (e.g. amulet damaged when only sword insured) → CLI exits non-zero, error to stderr");
  it.todo("claim references damage entry with unknown item type → CLI exits non-zero, error to stderr");
  it.todo("claim contains a damage entry with amount: -200 → CLI exits non-zero, error to stderr");
});

describe("CLI integration (schema example)", () => {
  it.todo("schema example: amulet quote followed by fire claim → stdout results array matches shape {premium} then {payout, remainingCap}");
});

