const reimbursementAmount = (item: Item, damageAmount: number): number => {
  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD) {
    return damageAmount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE;
  }
  return damageAmount;
};

export const calculatePayout = (
  policyItems: Item[],
  damages: Damage[],
): PayoutResult => {
  const damage = damages[0];
  const item = policyItems.find((i) => i.type === damage.itemType)!;
  const payout = reimbursementAmount(item, damage.amount) - DEDUCTIBLE;
  return { payout, remainingCap: 0 };
};

