import type { Item } from "./premium.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface PayoutResult {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE = 100;

export const calculatePayout = (
  policyItems: Item[],
  damages: Damage[],
): PayoutResult => {
  const payout = damages[0].amount - DEDUCTIBLE;
  return { payout, remainingCap: 0 };
};

